      "evidenceAgainst": []
    },
    {
      "label": "H2: A real weekly environmental cycle (e.g., temperature, settlement activity) modulates the pendulum_obs measurements.",
      "probability": 0.08,
      "rationale": "The pendulum_obs series shows the strongest autocorrelation at a 7‑day lag (–0.607) among all examined lags, hinting—but not confirming—a weekly pattern that could arise from routine settlement processes.",
      "evidenceFor": [887430, 222570, 5134, 440540, 403592, 1040118],
      "evidenceAgainst": []      
    },
    {
      "label": "H3: A periodic instrumental systematic (e.g., calibration or clock drift) introduces a spurious ~7‑day artifact in the pendulum_obs data.",
      "probability": 0.07,
      "rationale": "If calibrations or maintenance occur on a weekly schedule, they could imprint a subtle periodicity. No direct record of such a schedule exists, making this hypothesis plausible but unsubstantiated.",
      "evidenceFor": [],
      "evidenceAgainst": []
    },
    {
      "label": "H4: An external perturbation (e.g., power usage, communal activities) affects multiple instruments, producing weak correlated signals.",
      "probability": 0.04,
      "rationale": "Cross‑instrument agreements are all well below their respective chance thresholds, offering only a minimal suggestion of a common external driver.",
      "evidenceFor": [],
      "evidenceAgainst": []
    }
  ],
